sol = [0, 1, 27, 2, 26, 8, 6, 3, 18, 17, 25, 4, 12, 5, 21]
from itertools import combinations
edges = []
for g in range(5):
    for i,j in combinations(range(3),2):
        edges.append((g*3+i, g*3+j))
for g in range(4):
    for i in range(3):
        edges.append((g*3+i, (g+1)*3+i))
elab = [abs(sol[u]-sol[v]) for u,v in edges]
print(sorted(elab))
print(len(set(elab)), len(edges))
print(len(set(sol)), min(sol), max(sol))
